import { useState, useEffect } from "react";
import { motion } from "framer-motion";
import Papa from "papaparse";
import "../App.css";

function ResourcesPage() {
  const [activeRoomCategory, setActiveRoomCategory] = useState("all");
  const [activeSmallCategory, setActiveSmallCategory] = useState("all");
  const [searchText, setSearchText] = useState("");
  const [furnitureData, setFurnitureData] = useState([]);
  const [roomCategories, setRoomCategories] = useState([]);
  const [smallCategories, setSmallCategories] = useState([]);

  // Animation variants
  const fadeUp = {
    hidden: { opacity: 0, y: 40 },
    visible: { opacity: 1, y: 0, transition: { duration: 0.6, ease: "easeOut" } },
  };

  const staggerContainer = {
    hidden: { opacity: 0 },
    visible: {
      opacity: 1,
      transition: {
        staggerChildren: 0.1,
      },
    },
  };

  // CSV 파일에서 데이터 로드
  useEffect(() => {
    fetch("/20251020_가구종합.csv")
      .then((response) => {
        console.log("CSV 파일 로드 응답:", response);
        return response.text();
      })
      .then((csvText) => {
        console.log("CSV 텍스트 길이:", csvText.length);
        Papa.parse(csvText, {
          header: true,
          skipEmptyLines: true,
          complete: (results) => {
            console.log("파싱 결과:", results);
            console.log("첫 번째 행:", results.data[0]);

            const data = results.data.map((item, index) => ({
              id: item.goods_id || index,
              name: item.goods_name,
              price: item.price,
              imageUrl: item["Image URL"],
              roomName: item.room_name,
              smallCatName: item.small_cat_name,
            }));

            console.log("변환된 데이터 샘플:", data.slice(0, 3));
            console.log("총 데이터 개수:", data.length);
            setFurnitureData(data);

            // room_name으로 카테고리 추출
            const uniqueRooms = [...new Set(data.map((item) => item.roomName))].filter(Boolean);
            console.log("고유한 room 카테고리:", uniqueRooms);
            setRoomCategories([{ id: "all", label: "전체" }, ...uniqueRooms.map((room) => ({ id: room, label: room }))]);

            // small_cat_name으로 서브 카테고리 추출
            const uniqueSmallCats = [...new Set(data.map((item) => item.smallCatName))].filter(Boolean);
            console.log("고유한 small 카테고리:", uniqueSmallCats);
            setSmallCategories([{ id: "all", label: "전체" }, ...uniqueSmallCats.map((cat) => ({ id: cat, label: cat }))]);
          },
        });
      })
      .catch((error) => console.error("CSV 로드 오류:", error));
  }, []);

  // 필터링 로직
  const filteredFurniture = furnitureData.filter((item) => {
    const roomMatch = activeRoomCategory === "all" || item.roomName === activeRoomCategory;
    const smallCatMatch = activeSmallCategory === "all" || item.smallCatName === activeSmallCategory;
    const searchMatch = item.name?.toLowerCase().includes(searchText.toLowerCase());
    return roomMatch && smallCatMatch && searchMatch;
  });

  console.log("필터링된 가구 개수:", filteredFurniture.length);
  console.log("필터링된 가구 샘플:", filteredFurniture.slice(0, 2));

  // room 카테고리 변경 시 small 카테고리 필터링
  const availableSmallCategories = activeRoomCategory === "all"
    ? smallCategories
    : [
        { id: "all", label: "전체" },
        ...smallCategories.filter((cat) =>
          furnitureData.some(
            (item) => item.roomName === activeRoomCategory && item.smallCatName === cat.id
          )
        ).filter(cat => cat.id !== "all"),
      ];

  return (
    <main
      style={{
        minHeight: "100vh",
        background: "linear-gradient(180deg, #f8f9fa 0%, #e9ecef 100%)",
        paddingTop: "0",
        marginTop: "0",
      }}
    >
      {/* Header Section */}
      <motion.div
        style={{
          textAlign: "center",
          padding: "60px 20px 40px",
          background: "linear-gradient(135deg, #667eea 0%, #764ba2 100%)",
          color: "#fff",
          marginBottom: "50px",
          marginTop: "0",
        }}
        initial="hidden"
        animate="visible"
        variants={fadeUp}
      >
        <motion.h1
          style={{
            fontSize: "clamp(2.5rem, 5vw, 3.5rem)",
            fontWeight: 800,
            margin: "0 0 15px",
            textShadow: "2px 2px 4px rgba(0,0,0,0.2)",
          }}
          variants={fadeUp}
        >
          한샘 가구 둘러보기
        </motion.h1>
        <motion.p
          style={{
            fontSize: "1.2rem",
            opacity: 0.95,
            margin: 0,
          }}
          variants={fadeUp}
        >
          다양한 스타일의 가구를 탐색하고 영감을 얻으세요
        </motion.p>
      </motion.div>

      {/* Controls Section */}
      <motion.div
        style={{
          maxWidth: "1200px",
          margin: "0 auto 40px",
          padding: "0 20px",
        }}
        initial="hidden"
        whileInView="visible"
        viewport={{ once: true }}
        variants={fadeUp}
      >
        {/* Room Category Filters (큰 카테고리) */}
        <div style={{ marginBottom: "20px" }}>
          <h3 style={{
            textAlign: "center",
            fontSize: "1.1rem",
            fontWeight: 600,
            color: "#495057",
            marginBottom: "15px"
          }}>
            공간 선택
          </h3>
          <div
            style={{
              display: "flex",
              flexWrap: "wrap",
              gap: "12px",
              justifyContent: "center",
            }}
          >
            {roomCategories.map((category) => (
              <motion.button
                key={category.id}
                onClick={() => {
                  setActiveRoomCategory(category.id);
                  setActiveSmallCategory("all");
                }}
                style={{
                  padding: "12px 24px",
                  border: "none",
                  borderRadius: "25px",
                  fontSize: "1rem",
                  fontWeight: 600,
                  cursor: "pointer",
                  transition: "all 0.3s ease",
                  background:
                    activeRoomCategory === category.id
                      ? "linear-gradient(135deg, #667eea 0%, #764ba2 100%)"
                      : "#fff",
                  color: activeRoomCategory === category.id ? "#fff" : "#333",
                  boxShadow:
                    activeRoomCategory === category.id
                      ? "0 8px 20px rgba(102, 126, 234, 0.3)"
                      : "0 2px 8px rgba(0, 0, 0, 0.08)",
                }}
                whileHover={{
                  scale: 1.05,
                  boxShadow: "0 10px 25px rgba(102, 126, 234, 0.4)",
                }}
                whileTap={{ scale: 0.95 }}
              >
                {category.label}
              </motion.button>
            ))}
          </div>
        </div>

        {/* Small Category Filters (작은 카테고리) */}
        <div style={{ marginBottom: "30px" }}>
          <h3 style={{
            textAlign: "center",
            fontSize: "1.1rem",
            fontWeight: 600,
            color: "#495057",
            marginBottom: "15px"
          }}>
            가구 종류
          </h3>
          <div
            style={{
              display: "flex",
              flexWrap: "wrap",
              gap: "12px",
              justifyContent: "center",
            }}
          >
            {availableSmallCategories.map((category) => (
              <motion.button
                key={category.id}
                onClick={() => setActiveSmallCategory(category.id)}
                style={{
                  padding: "10px 20px",
                  border: "none",
                  borderRadius: "20px",
                  fontSize: "0.95rem",
                  fontWeight: 600,
                  cursor: "pointer",
                  transition: "all 0.3s ease",
                  background:
                    activeSmallCategory === category.id
                      ? "linear-gradient(135deg, #f093fb 0%, #f5576c 100%)"
                      : "#fff",
                  color: activeSmallCategory === category.id ? "#fff" : "#333",
                  boxShadow:
                    activeSmallCategory === category.id
                      ? "0 6px 15px rgba(245, 87, 108, 0.3)"
                      : "0 2px 8px rgba(0, 0, 0, 0.08)",
                }}
                whileHover={{
                  scale: 1.05,
                  boxShadow: "0 8px 20px rgba(245, 87, 108, 0.4)",
                }}
                whileTap={{ scale: 0.95 }}
              >
                {category.label}
              </motion.button>
            ))}
          </div>
        </div>

        {/* Search Bar */}
        <div
          style={{
            maxWidth: "500px",
            margin: "0 auto",
            position: "relative",
          }}
        >
          <i
            className="fas fa-search"
            style={{
              position: "absolute",
              left: "20px",
              top: "50%",
              transform: "translateY(-50%)",
              color: "#999",
              fontSize: "1.1em",
            }}
          ></i>
          <input
            type="text"
            placeholder="가구 검색..."
            value={searchText}
            onChange={(e) => setSearchText(e.target.value)}
            style={{
              width: "100%",
              padding: "16px 20px 16px 50px",
              border: "2px solid #e9ecef",
              borderRadius: "25px",
              fontSize: "1rem",
              boxSizing: "border-box",
              transition: "all 0.3s ease",
              background: "#fff",
            }}
            onFocus={(e) => {
              e.target.style.borderColor = "#667eea";
              e.target.style.boxShadow = "0 0 0 4px rgba(102, 126, 234, 0.1)";
            }}
            onBlur={(e) => {
              e.target.style.borderColor = "#e9ecef";
              e.target.style.boxShadow = "none";
            }}
          />
        </div>
      </motion.div>

      {/* Furniture Grid */}
      <motion.div
        style={{
          maxWidth: "1200px",
          margin: "0 auto",
          padding: "0 20px",
        }}
        initial="hidden"
        whileInView="visible"
        viewport={{ once: true, amount: 0.1 }}
        variants={staggerContainer}
      >
        <div
          style={{
            display: "grid",
            gridTemplateColumns: "repeat(auto-fill, minmax(280px, 1fr))",
            gap: "30px",
          }}
        >
          {filteredFurniture.length > 0 ? (
            filteredFurniture.map((item) => (
              <motion.div
                key={item.id}
                style={{
                  backgroundColor: "#fff",
                  borderRadius: "20px",
                  overflow: "hidden",
                  boxShadow: "0 10px 30px rgba(0, 0, 0, 0.08)",
                  transition: "all 0.3s ease",
                  cursor: "pointer",
                }}
                variants={fadeUp}
                whileHover={{
                  y: -10,
                  boxShadow: "0 20px 40px rgba(0, 0, 0, 0.15)",
                }}
              >
                {/* Image */}
                <div
                  style={{
                    width: "100%",
                    height: "220px",
                    overflow: "hidden",
                    position: "relative",
                  }}
                >
                  <img
                    src={item.imageUrl}
                    alt={item.name}
                    style={{
                      width: "100%",
                      height: "100%",
                      objectFit: "cover",
                      transition: "transform 0.3s ease",
                    }}
                    onMouseEnter={(e) => {
                      e.target.style.transform = "scale(1.1)";
                    }}
                    onMouseLeave={(e) => {
                      e.target.style.transform = "scale(1)";
                    }}
                    onError={(e) => {
                      e.target.src = "https://via.placeholder.com/500x300?text=No+Image";
                    }}
                  />
                  {/* Category Badge */}
                  <div
                    style={{
                      position: "absolute",
                      top: "15px",
                      right: "15px",
                      padding: "6px 14px",
                      background: "rgba(255, 255, 255, 0.95)",
                      backdropFilter: "blur(10px)",
                      borderRadius: "15px",
                      fontSize: "0.85em",
                      fontWeight: 600,
                      color: "#667eea",
                    }}
                  >
                    {item.smallCatName}
                  </div>
                </div>

                {/* Info */}
                <div style={{ padding: "25px" }}>
                  <h3
                    style={{
                      fontSize: "1.3em",
                      fontWeight: 700,
                      margin: "0 0 12px",
                      color: "#333",
                    }}
                  >
                    {item.name}
                  </h3>
                  <div style={{
                    display: "flex",
                    justifyContent: "space-between",
                    alignItems: "center",
                    marginBottom: "8px"
                  }}>
                    <span style={{
                      fontSize: "0.9em",
                      color: "#6c757d",
                    }}>
                      {item.roomName}
                    </span>
                    <span style={{
                      fontSize: "1.1em",
                      fontWeight: 700,
                      color: "#667eea",
                    }}>
                      {item.price ? `₩${parseInt(item.price).toLocaleString()}` : ""}
                    </span>
                  </div>
                </div>
              </motion.div>
            ))
          ) : (
            <motion.div
              style={{
                gridColumn: "1 / -1",
                textAlign: "center",
                padding: "60px 20px",
              }}
              variants={fadeUp}
            >
              <i
                className="fas fa-search"
                style={{
                  fontSize: "4em",
                  color: "#dee2e6",
                  marginBottom: "20px",
                  display: "block",
                }}
              ></i>
              <h3 style={{ fontSize: "1.5em", color: "#6c757d", margin: 0 }}>
                검색 결과가 없습니다
              </h3>
              <p style={{ color: "#adb5bd", marginTop: "10px" }}>
                다른 검색어나 카테고리를 선택해보세요
              </p>
            </motion.div>
          )}
        </div>
      </motion.div>

      {/* Results Count */}
      {filteredFurniture.length > 0 && (
        <motion.div
          style={{
            textAlign: "center",
            marginTop: "50px",
            color: "#6c757d",
            fontSize: "1rem",
          }}
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ delay: 0.3 }}
        >
          총 <strong style={{ color: "#667eea" }}>{filteredFurniture.length}</strong>개의 가구를
          찾았습니다
        </motion.div>
      )}
    </main>
  );
}

export default ResourcesPage;
